// The agency keys, arranged the way they are actually worked.
//
// connectionRegistry.ts already declares every credential, but it declares them
// by INTEGRATION, which is the right shape for "what went dark" and the wrong
// shape for "I have eight keys to paste in". This file is the second view: the
// same keys, grouped by what they switch on, and marked with how each one is
// obtained. A key is pasted from a vendor dashboard, generated by us, or locked.
//
// The catalogue is asserted against the registry in the tests, so a credential
// added to one and forgotten in the other fails the build rather than quietly
// vanishing from the screen an operator relies on.

import { CONNECTIONS } from "./connectionRegistry";
import type { AgencySecretRow } from "./secretsApi";

