/** How a key is obtained, which decides what control it gets. */
export type KeyEntry =
  /** Pasted from a vendor dashboard. */
  | "paste"
  /** Invented by us. Gets a Generate button. */
  | "generate"
  /** Shown, never editable here. See LOCK_REASON. */
  | "locked";

export type Generator = "hex32" | "vapid";

export interface AgencyKeyDef {
  name: string;
  group: string;
  entry: KeyEntry;
  /** Where to find it, or what it is. */
  help: string;
  /** The consequence of changing it. Printed before the value is replaced. */
  warning?: string;
  /** Only for entry: "generate". */
  generator?: Generator;
  /**
   * Generated alongside another key, so the UI offers one button for the pair
   * rather than two that would produce a mismatched public and private half.
   */
  pairedWith?: string;
}

/**
 * Why a key cannot be edited here.
 *
 * The first three grant this page its own power. A screen that can rewrite the
 * credentials it authenticates with can lock you out of itself permanently, or
 * quietly widen its own access, and neither failure announces itself. They stay
 * a command-line job. The Supabase three are read-only for a different reason:
 * a new client needs no input there at all, so an editable box would imply work
 * that does not exist.
 */
export const LOCK_REASON: Record<string, string> = {
  CF_DEPLOY_TOKEN: "Grants this page its deploy power. Editable here, it could revoke its own access.",
  DOPPLER_TOKEN: "Grants this page its read of Doppler. Same reason.",
  DOPPLER_WRITE_TOKEN: "Grants this page its write to Doppler. Same reason.",
  CLOUDFLARE_ACCOUNT_ID: "Names the account this app deploys into. Changing it here would point Apply at nothing.",
  CF_PAGES_PROJECT: "Names the Pages project. Same reason.",
  SUPABASE_URL: "Set once. A new client needs nothing here.",
  SUPABASE_SERVICE_ROLE_KEY: "Set once. A new client needs nothing here.",
  SUPABASE_ANON_KEY: "Set once. A new client needs nothing here.",
};

