/** Keys the write endpoint must refuse, whatever the UI does. */
export const LOCKED_KEYS: string[] = AGENCY_KEYS.filter((k) => k.entry === "locked").map((k) => k.name);

export function isLocked(name: string): boolean {
  return LOCKED_KEYS.includes(name);
}

export function keyDef(name: string): AgencyKeyDef | undefined {
  return AGENCY_KEYS.find((k) => k.name === name);
}

/** Every Cloudflare-homed credential the registry declares, deduplicated. */
export function registryKeyNames(): string[] {
  const names = new Set<string>();
  for (const def of CONNECTIONS) {
    for (const c of def.credentials) {
      if (c.home === "cloudflare") names.add(c.name);
    }
  }
  return [...names].sort();
}

// --- Status ------------------------------------------------------------------

/**
 * What one key is doing right now.
 *
 * `pending` is the state this whole build exists to make visible: Doppler has
 * the new value and the running app does not, which until now was reported as
 * a drift warning and a shell command rather than as a thing you could finish.
 */
export type KeyStatus = "live" | "pending" | "missing";

export function keyStatus(row: AgencySecretRow): KeyStatus {
  if (!row.inDoppler && !row.inRuntime) return "missing";
  // In Doppler but absent from the deploy, or present in both and different:
  // either way the running app is not serving what Doppler says it should.
  if (row.inDoppler && (!row.inRuntime || row.drift === true)) return "pending";
  return "live";
}

export const STATUS_LABEL: Record<KeyStatus, string> = {
  live: "Live",
  pending: "Saved, pending restart",
  missing: "Not set",
};

/** The keys an Apply would actually change. Drives the footer count. */
export function pendingKeys(rows: AgencySecretRow[]): AgencySecretRow[] {
  return rows.filter((r) => keyStatus(r) === "pending");
}

export interface GroupedKeys {
  group: KeyGroup;
  keys: { def: AgencyKeyDef; row: AgencySecretRow | null }[];
}

/**
 * The catalogue joined to live status, in group order.
 *
 * A key the server reports but the catalogue has never heard of still appears,
 * under "Not in use", rather than being dropped: an unknown key on this screen
 * is a prompt to file it, and silently hiding one is how a credential goes
 * missing for a month.
 */
export function groupedKeys(rows: AgencySecretRow[]): GroupedKeys[] {
  const byName = new Map(rows.map((r) => [r.name, r]));
  const known = new Set(AGENCY_KEYS.map((k) => k.name));

  const strays: AgencyKeyDef[] = rows
    .filter((r) => !known.has(r.name))
    .map((r) => ({
      name: r.name,
      group: "unused",
      entry: "paste" as KeyEntry,
      help: "Declared by an integration but not yet filed into a group here.",
    }));

  const all = [...AGENCY_KEYS, ...strays];

  return KEY_GROUPS.map((group) => ({
    group,
    keys: all
      .filter((k) => k.group === group.id)
      .map((def) => ({ def, row: byName.get(def.name) ?? null })),
  })).filter((g) => g.keys.length > 0);
}
